metria.malla_08.retenido + tables.granulometria.malla_10.retenido + tables.granulometria.malla_16.retenido + tables.granulometria.malla_20.retenido + tables.granulometria.malla_30.retenido + tables.granulometria.malla_40.retenido + tables.granulometria.malla_50.retenido + tables.granulometria.malla_60.retenido + tables.granulometria.malla_100.retenido + tables.granulometria.malla_140.retenido + tables.granulometria.malla_200.retenido", "_intermediate.base_total": "= general_fields.peso_total", "_intermediate.suma_coarse": "= tables.granulometria.malla_3p.retenido + tables.granulometria.malla_2p5.retenido + tables.granulometria.malla_2p.retenido + tables.granulometria.malla_1p5.retenido + tables.granulometria.malla_1p.retenido + tables.granulometria.malla_3p4.retenido + tables.granulometria.malla_1p2.retenido + tables.granulometria.malla_3p8.retenido + tables.granulometria.malla_1p4.retenido + tables.granulometria.malla_04.retenido", "calculated_values.sucs.cc": "= (calculated_values.sucs.d10 * calculated_values.sucs.d60 > 0 ? (calculated_values.sucs.d30 * calculated_values.sucs.d30) / (calculated_values.sucs.d10 * calculated_values.sucs.d60) : 0)", "calculated_values.sucs.cu": "= (calculated_values.sucs.d10 > 0 ? calculated_values.sucs.d60 / calculated_values.sucs.d10 : 0)", "calculated_values.sucs.ip": "= (general_fields.indice_plasticidad > 0 ? general_fields.indice_plasticidad : 0)", "calculated_values.sucs.ll": "= (general_fields.limite_liquido > 0 ? general_fields.limite_liquido : 0)", "_functions.clasificar_sucs": "function(grava, arena, finos, d10, d30, d60, ll, ip) {\n          var F = Number(finos) || 0;\n          var G = Number(grava) || 0;\n          var S = Number(arena) || 0;\n          var LL = Number(ll) || 0;\n          var IP = Number(ip) || 0;\n          var D10 = Number(d10) || 0;\n          var D30 = Number(d30) || 0;\n          var D60 = Number(d60) || 0;\n          var cu = D10 > 0 ? D60 / D10 : 0;\n          var cc = (D10 * D60) > 0 ? (D30 * D30) / (D10 * D60) : 0;\n          var lineaA = 0.73 * (LL - 20);\n          var esArcilloso = IP >= 7 && IP >= lineaA;\n          var esLimoso = IP < 4 || IP < lineaA;\n          if (F >= 50) {\n              if (LL < 50) {\n                  if (IP >= 7 && IP >= lineaA) return \"CL\";\n                  if (IP < 4 || IP < lineaA) return \"ML\";\n                  return \"CL-ML\";\n              } else {\n                  if (IP >= lineaA) return \"CH\";\n                  return \"MH\";\n              }\n          }\n          var esGrava = G > S;\n          if (esGrava) {\n              if (F < 5) {\n                  var bienGraduada = cu >= 4 && cc >= 1 && cc <= 3;\n                  return bienGraduada ? \"GW\" : \"GP\";\n              } else if (F > 12) {\n                  if (esArcilloso) return \"GC\";\n                  if (esLimoso) return \"GM\";\n                  return \"GC-GM\";\n              } else {\n                  var bienGraduada = cu >= 4 && cc >= 1 && cc <= 3;\n                  if (esArcilloso) return bienGraduada ? \"GW-GC\" : \"GP-GC\";\n                  if (esLimoso) return bienGraduada ? \"GW-GM\" : \"GP-GM\";\n                  return bienGraduada ? \"GW-GC\" : \"GP-GC\";\n              }\n          } else {\n              if (F < 5) {\n                  var bienGraduada = cu >= 6 && cc >= 1 && cc <= 3;\n                  return bienGraduada ? \"SW\" : \"SP\";\n              } else if (F > 12) {\n                  if (esArcilloso) return \"SC\";\n                  if (esLimoso) return \"SM\";\n                  return \"SC-SM\";\n              } else {\n                  var bienGraduada = cu >= 6 && cc >= 1 && cc <= 3;\n                  if (esArcilloso) return bienGraduada ? \"SW-SC\" : \"SP-SC\";\n                  if (esLimoso) return bienGraduada ? \"SW-SM\" : \"SP-SM\";\n                  return bienGraduada ? \"SW-SC\" : \"SP-SC\";\n              }\n          }\n      }", "calculated_values.sucs.d10": "= calcular_dx(tableConfig.tables.granulometria.rows, tables.granulometria, 10)", "calculated_values.sucs.d30": "= calcular_dx(tableConfig.tables.granulometria.rows, tables.granulometria, 30)", "calculated_values.sucs.d50": "= calcular_dx(tableConfig.tables.granulometria.rows, tables.granulometria, 50)", "calculated_values.sucs.d60": "= calcular_dx(tableConfig.tables.granulometria.rows, tables.granulometria, 60)", "general_fields.coeficiente": "= (general_fields.peso_total > 0 ? general_fields.peso_fraccion_fina / general_fields.peso_total : 0)", "_functions.clasificar_aashto": "function(pasa10, pasa40, pasa200, ll, ip) {\n          var F10 = Number(pasa10) || 0;\n          var F40 = Number(pasa40) || 0;\n          var F200 = Number(pasa200) || 0;\n          var LL = Number(ll) || 0;\n          var IP = Number(ip) || 0;\n          var grupo = \"\";\n          var ig = 0;\n          if (F200 <= 35) {\n              if (F10 <= 50 && F40 <= 30 && F200 <= 15 && IP <= 6) {\n                  grupo = \"A-1-a\";\n                  ig = 0;\n              } else if (F40 <= 50 && F200 <= 25 && IP <= 6) {\n                  grupo = \"A-1-b\";\n                  ig = 0;\n              } else if (F40 >= 51 && F200 <= 10 && IP <= 0) {\n                  grupo = \"A-3\";\n                  ig = 0;\n              } else {\n                  if (LL <= 40) {\n                      if (IP <= 10) {\n                          grupo = \"A-2-4\";\n                          ig = 0;\n                      } else {\n                          grupo = \"A-2-6\";\n                          ig = Math.max(0, Math.round(0.01 * (F200 - 15) * (IP - 10)));\n                      }\n                  } else {\n                      if (IP <= 10) {\n                          grupo = \"A-2-5\";\n                          ig = 0;\n                      } else {\n                          grupo = \"A-2-7\";\n                          ig = Math.max(0, Math.round(0.01 * (F200 - 15) * (IP - 10)));\n                      }\n                  }\n              }\n          } else {\n              var igTerm1 = (F200 - 35) * (0.2 + 0.005 * (LL - 40));\n              var igTerm2 = 0.01 * (F200 - 15) * (IP - 10);\n              ig = Math.max(0, Math.round(igTerm1 + igTerm2));\n              if (LL <= 40) {\n                  if (IP <= 10) {\n                      grupo = \"A-4\";\n                  } else {\n                      grupo = \"A-6\";\n                  }\n              } else {\n                  if (IP <= 10) {\n                      grupo = \"A-5\";\n                  } else {\n                      if (IP <= LL - 30) {\n                          grupo = \"A-7-5\";\n                      } else {\n                          grupo = \"A-7-6\";\n                      }\n                  }\n              }\n          }\n          return grupo + \" (\" + ig + \")\";\n      }", "calculated_values.sucs.arena": "= tables.granulometria.malla_04.pasa - tables.granulometria.malla_200.pasa", "calculated_values.sucs.finos": "= tables.granulometria.malla_200.pasa", "calculated_values.sucs.grava": "= tables.granulometria.malla_04.acum_retenido_porcentaje", "calculated_values.sucs.pasa_10": "= tables.granulometria.malla_10.pasa", "calculated_values.sucs.pasa_40": "= tables.granulometria.malla_40.pasa", "calculated_values.sucs.pasa_200": "= tables.granulometria.malla_200.pasa", "tables.granulometria.total.pasa": "= 0", "calculated_values.sucs.tm_nominal": "= tables.granulometria.total.acum_retenido_porcentaje >= 0 ? obtener_tmn(tableConfig.tables.granulometria.rows, tables.granulometria) : \"N/A\"", "general_fields.peso_fraccion_fina": "= general_fields.peso_total - general_fields.peso_fraccion_gruesa", "general_fields.peso_muestra_lavada": "= general_fields.peso_fraccion_gruesa + (general_fields.peso_fina_tamizada > 0 ? (_intermediate.suma_fine * (general_fields.peso_fraccion_fina / general_fields.peso_fina_tamizada)) : 0)", "tables.granulometria.malla_04.pasa": "= 100 - tables.granulometria.mall